<?php
namespace App\Http\Controllers;
use App\Models\Vehicle; use Illuminate\Http\Request;
class VehicleController extends Controller { public function index(){ $vehicles=Vehicle::with('activeMovement.driver')->latest()->paginate(15); return view('admin.vehicles.index',compact('vehicles')); } public function create(){return view('admin.vehicles.create');} public function store(Request $r){$d=$r->validate(['number'=>'required|string|max:80|unique:vehicles,number','type'=>'required|string|max:100','model'=>'nullable|string|max:100','description'=>'nullable|string']); Vehicle::create(array_merge($d,['active'=>true])); return redirect()->route('vehicles.index')->with('success','ئۆتۆمبێل زیادکرا.');} public function edit(Vehicle $vehicle){return view('admin.vehicles.edit',compact('vehicle'));} public function update(Request $r,Vehicle $vehicle){$d=$r->validate(['number'=>'required|string|max:80|unique:vehicles,number,'.$vehicle->id,'type'=>'required|string|max:100','model'=>'nullable|string|max:100','description'=>'nullable|string','active'=>'nullable|boolean']); $vehicle->update($d); return redirect()->route('vehicles.index')->with('success','زانیاری ئۆتۆمبێل نوێکرایەوە.');} public function destroy(Vehicle $vehicle){if($vehicle->movements()->where('status','out')->exists()) return back()->with('error','ئەم ئۆتۆمبێلە ئێستا لە دەرەوەیە.'); $vehicle->update(['active'=>false]); return back()->with('success','ئۆتۆمبێل ناچالاک کرا.');} }
